definition.script:
import groovy.json.JsonSlurper;

def retrieveBuildSpecId;
def pipelineBuildId;
def build_hashes = [
    PSA: false,
];
pipeline {
    agent any
    options {
        disableConcurrentBuilds()
    }
    stages {
        stage('Retrieve Build Spec') {
            steps {
                script {
                    if (!(params.release_control_commit ==~ /[0-9a-f]{40}/)) {
                        error('PIC-SURE Pipeline requires an exact release_control_commit; use Check For Updates.')
                    }
                    def result = build job: 'Retrieve Pinned Build Spec', parameters: [
                        [$class: 'StringParameterValue', name: 'release_control_commit', value: params.release_control_commit]
                    ]
                    retrieveBuildSpecId = result.number
                }
                script {
                    copyArtifacts filter: '*', projectName: 'Retrieve Pinned Build Spec', selector: specific(""+retrieveBuildSpecId)
                    sh 'cat build-spec.json'
                    sh 'cat pipeline_git_commit.txt'
                    sh '/scripts/validate-build-spec.sh build-spec.json'
                    def buildSpec = new JsonSlurper().parse(new File('/var/jenkins_home/workspace/PIC-SURE Pipeline/build-spec.json'))
                    pipelineBuildId = new File('/var/jenkins_home/workspace/PIC-SURE Pipeline/pipeline_git_commit.txt').text.trim()
                    for(def build : buildSpec.application){
                        build_hashes[build.project_job_git_key] = build.git_hash
                    }
                }
            }
        }
        stage('Verify Migrations') {
            steps {
                script {
                    if (!(params.migration_build_number ==~ /[1-9][0-9]*/)) {
                        error('PIC-SURE Pipeline requires a successful migration_build_number; use Check For Updates.')
                    }
                    build job: 'Verify PIC-SURE Database Migration', parameters: [
                        [$class: 'StringParameterValue', name: 'migration_build_number', value: params.migration_build_number]
                    ]
                    sh 'rm -f migration-release-control-commit.txt'
                    copyArtifacts filter: 'migration-release-control-commit.txt',
                        projectName: 'PIC-SURE Database Migrations',
                        selector: specific(params.migration_build_number)
                    def migratedCommit = new File('/var/jenkins_home/workspace/PIC-SURE Pipeline/migration-release-control-commit.txt').text.trim()
                    if (migratedCommit != params.release_control_commit) {
                        error("Migration build ${params.migration_build_number} used release-control commit ${migratedCommit}, expected ${params.release_control_commit}.")
                    }
                }
            }
        }
        stage('Maven Build') {
            when { expression { return build_hashes['PSA'] } }
            steps {
                script {
                    build job: 'PIC-SURE Maven Build', parameters: [
                        [$class: 'StringParameterValue', name: 'pipeline_build_id', value: pipelineBuildId],
                        [$class: 'StringParameterValue', name: 'git_hash', value: build_hashes['PSA']]
                    ]
                }
            }
        }
        stage('Build Images') {
            steps {
                script {
                    def branches = [:]
                    if (build_hashes['PSA']) {
                        branches['gateway'] = {
                            build job: 'PIC-SURE Gateway Build and Deploy', parameters: [
                                [$class: 'StringParameterValue', name: 'pipeline_build_id', value: pipelineBuildId]
                            ]
                        }
                        branches['operations'] = {
                            build job: 'PIC-SURE Operations Service Build and Deploy', parameters: [
                                [$class: 'StringParameterValue', name: 'pipeline_build_id', value: pipelineBuildId]
                            ]
                        }
                        branches['query'] = {
                            build job: 'PIC-SURE HPDS Query Service Build and Deploy', parameters: [
                                [$class: 'StringParameterValue', name: 'pipeline_build_id', value: pipelineBuildId]
                            ]
                        }
                        branches['hpds'] = {
                            build job: 'PIC-SURE-HPDS Build', parameters: [
                                [$class: 'StringParameterValue', name: 'pipeline_build_id', value: pipelineBuildId]
                            ]
                        }
                        branches['visualization'] = {
                            sh """
                                if [ ! -f /usr/local/docker-config/visualization/visualization.env ]; then
                                    mkdir -p /usr/local/docker-config/visualization
                                    echo 'SERVER_PORT=80' > /usr/local/docker-config/visualization/visualization.env
                                    echo 'HPDS_QUERY_SERVICE_URL=http://pic-sure-hpds-query-service:8080' >> /usr/local/docker-config/visualization/visualization.env
                                    echo 'PICSURE_ACTUATOR_EXPOSURE=health' >> /usr/local/docker-config/visualization/visualization.env
                                else
                                    echo 'visualization.env already exists; leaving existing config untouched.'
                                fi
                            """
                            build job: 'PIC-SURE Visualization Build and Deploy', parameters: [
                                [$class: 'StringParameterValue', name: 'pipeline_build_id', value: pipelineBuildId]
                            ]
                        }
                        branches['auth'] = {
                            build job: 'PIC-SURE Auth Micro-App Build - Jenkinsfile', parameters: [
                                [$class: 'StringParameterValue', name: 'pipeline_build_id', value: pipelineBuildId]
                            ]
                        }
                        branches['logging'] = {
                            build job: 'PIC-SURE Logging Build and Deploy', parameters: [
                                [$class: 'StringParameterValue', name: 'pipeline_build_id', value: pipelineBuildId]
                            ]
                        }
                        branches['dictionary'] = {
                            build job: 'PIC-SURE Dictionary API Build and Deploy', parameters: [
                                [$class: 'StringParameterValue', name: 'pipeline_build_id', value: pipelineBuildId]
                            ]
                        }
                    } else {
                        echo "No project_job_git_key PSA found in build spec. Skipping monorepo image builds."
                    }
                    branches['frontend'] = {
                        build job: 'PIC-SURE Frontend Build', parameters: [
                            [$class: 'StringParameterValue', name: 'pipeline_build_id', value: pipelineBuildId],
                            [$class: 'StringParameterValue', name: 'git_hash', value: build_hashes['PSF']]
                        ]
                    }
                    parallel branches
                }
            }
        }
        stage('Restart Stack') {
            steps {
                script {
                    build job: 'Stop PIC-SURE'
                    build job: 'Start PIC-SURE'
                }
            }
        }
    }
}
